#!/usr/bin/env bash
# codex_comms.sh: open Codex in this tab as the legatus "comms". Generated by tools/legati/make-launchers.sh.
# Thin wrapper over legati/bin/legatus (sets LEGATUS_AGENT, names the tab, loads the boot file). Extra args go to the harness.
exec "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/legati/bin/legatus" comms codex "$@"
